        SELECT 
        FROM `refund`


                AND (
dish_name LIKE CONCAT('%', #{query.searchKeyword}, '%')
                OR refund_no LIKE CONCAT('%', #{query.searchKeyword}, '%')
                OR reason LIKE CONCAT('%', #{query.searchKeyword}, '%')
                )

            AND refund_no LIKE CONCAT('%', #{query.refundNo}, '%')
            AND dish_name LIKE CONCAT('%', #{query.dishName}, '%')
            AND reason LIKE CONCAT('%', #{query.reason}, '%')
            AND order_id = #{query.orderId}
            AND order_detail_id = #{query.orderDetailId}
            AND store_id = #{query.storeId}
            AND member_id = #{query.memberId}
            AND refund_type = #{query.refundType}
            AND quantity = #{query.quantity}
            AND status = #{query.status}
            AND operator_id = #{query.operatorId}
            AND create_time >= CONCAT(#{query.searchBeginTime}, ' 00:00:00')
            AND create_time <= CONCAT(#{query.searchEndTime}, ' 23:59:59')

        ORDER BY id DESC

