UPDATE `refund`
refund_no = #{refundNo}, order_id = #{orderId}, order_detail_id = #{orderDetailId}, store_id = #{storeId}, member_id = #{memberId}, refund_type = #{refundType}, dish_name = #{dishName}, quantity = #{quantity}, amount = #{amount}, reason = #{reason}, status = #{status}, operator_id = #{operatorId}, refund_time = #{refundTime}, create_time = #{createTime},
WHERE id = #{id}
